        expected_yield='',
        sections=[{'body': 'Cassia (Cassia auriculata) is propagated by seeds. During flowering tree is topped (stem and branches cut) and loppings used for green leaf manuring.', 'heading': 'Overview'}],
        source_reference='KAU Package of Practices Recommendations: Crops 2024 (16th ed.)',
