    dict(
        crop_name='Koovalam',
        crop_group='Medicinal and Aromatic Plants',
        season='',
        varieties=[{'name': 'North Indian and South Indian type', 'description': 'There are 2 types of Koovalam, North Indian type and South Indian type, of which North Indian type is suitable for cultivation. The fruits of these are edible.'}],
        spacing='Pits of size 60 cm x 60 cm x 45 cm are taken at a distance of 4 m.',
        manuring_fertilizer='The pit is covered with FYM @ 1 kg/pit and top soil.',
        plant_protection='',
        harvesting='',
        expected_yield='',
        sections=[{'body': 'In Sanskrit it is known as vilwam (Aegle marmelos) and it is one of the ingredients of "Dasamoola". The drug comprises of ripe or half ripe fruits of the tree. The fruit is very useful in chronic diarhoea and dysentery. The unripe or half ripe fruits improve appetite and digestion. The leaves and roots are effective against stomach complaints and diabetes.', 'heading': 'Overview'}, {'body': 'The fruits mature by December-January. The seeds are extracted from the fruit and dried under sun. The seeds are dipped in water for 6 hours and are sown in furrows. Mulch the furrows with dried leaves. The seeds will germinate within 15-20 days after planting and they are transplanted to poly bags at 5-6 leaf stage. 2 months old seedlings are used for field planting.', 'heading': 'Propagation'}, {'body': 'Plough the field. The seedlings are planted at the centre of pit. Irrigate the crop regularly.', 'heading': 'Land preparation and planting'}],
        source_reference='KAU Package of Practices Recommendations: Crops 2024 (16th ed.)',
        source_page_range='289-290 (book pp 276-277)',
        is_active=True,
    ),
